CREATE TABLE departments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),code VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL,active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE sections(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),department_id UUID NOT NULL REFERENCES departments(id),code VARCHAR(255) NOT NULL,name VARCHAR(255) NOT NULL,UNIQUE(department_id,code));
CREATE TABLE positions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),code VARCHAR(255) NOT NULL UNIQUE,name VARCHAR(255) NOT NULL);
CREATE TABLE employees(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),staff_id VARCHAR(30) NOT NULL UNIQUE,full_name VARCHAR(255) NOT NULL,department_id UUID REFERENCES departments(id),section_id UUID REFERENCES sections(id),position_id UUID REFERENCES positions(id),shift VARCHAR(100),location VARCHAR(255),supervisor_id UUID REFERENCES employees(id),status VARCHAR(30) NOT NULL CHECK(status IN('ACTIVE','INACTIVE','TERMINATED')));
ALTER TABLE users ADD CONSTRAINT fk_user_employee FOREIGN KEY(employee_id) REFERENCES employees(id);CREATE INDEX idx_employees_name ON employees(lower(full_name));